#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n;
    cin >> n;
    vector<long long> buckets[11];
    long long total_sum[11] = {0};
    const long long MOD1 = 998244353, MOD2 = 1000000007;
    long long counter = 0, temp_counter = 0, answer = 0;

    auto mod1_func = [&](long long x) {
        return (x % MOD1 + MOD1) % MOD1;
    };

    function<void(int, long long)> generate1 = [&](int level, long long value) {
        if (value > n) return;
        if (level > 6) return;
        ++counter;
        buckets[level].push_back(mod1_func(counter - value));
        total_sum[level] += mod1_func(counter - value);
        for (int digit = 0; digit < 10; ++digit) {
            generate1(level + 1, value * 10 + digit);
        }
    };

    function<void(int, long long)> generate2 = [&](int level, long long value) {
        if (value > n) return;
        if (level >= 1) {
            if (value * 10 * n > n && value * n + n - 1 <= n) {
                for (int i = 0; i <= 6; ++i) {
                    long long val = mod1_func(counter - value);
                    auto &vec = buckets[i];
                    auto pos = lower_bound(vec.begin(), vec.end(), MOD1 - val) - vec.begin();
                    answer = (answer + val * (long long)vec.size() + total_sum[i] - MOD1 * ((long long)vec.size() - pos)) % MOD2;
                }
                counter += temp_counter;
                return;
            }
            ++counter;
            answer = (answer + mod1_func(counter - value)) % MOD2;
        }
        for (int digit = (level == 0 ? 1 : 0); digit <= 9; ++digit) {
            generate2(level + 1, value * 10 + digit);
        }
    };

    generate1(0, 0);
    temp_counter = counter;
    counter = 0;
    for (int i = 0; i <= 6; ++i) {
        sort(buckets[i].begin(), buckets[i].end());
    }
    generate2(0, 0);
    cout << answer << "\n";
    return 0;
}
